'use strict';

// MODULES //

var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var isFiniteValue = require( '@stdlib/math/base/assert/is-finite' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// FUNCTIONS //

/**
* Validates selectors, dimensions and the required tolerance in that order.
* @private
* @param {string|integer} u - triangle
* @param {integer} N - order
* @param {number} tol - tolerance
* @throws {TypeError} invalid selector or nonprimitive tolerance
* @throws {RangeError} invalid dimension or nonfinite tolerance
* @returns {integer} triangle
*/
function scalars(u, N, tol) {
	if (((((u !== 'upper') && (u !== 'lower')) && (u !== 121)) && (u !== 122))) {
		throw new TypeError('invalid argument. Invalid triangle selector.');
	}
	if (((!isSafeInteger(N) || (N < 0)) || (N > 2147483647))) {
		throw new RangeError('invalid argument. Dimension must be a nonnegative signed32 integer.');
	}
	if ((typeof tol !== 'number')) {
		throw new TypeError('invalid argument. TOL must be a primitive finite Number.');
	}
	if (!isFiniteValue(tol)) {
		throw new RangeError('invalid argument. TOL must be finite.');
	}
	return ((u === 'upper') || (u === 121)) ? 121 : 122;
}


// MAIN //

/**
* Creates the contiguous and indexed factorization interfaces.
* @private
* @param {Function} base - normalized kernel
* @returns {Function} interface
*/
function factory(base) {
	setReadOnly(dpstf2, 'ndarray', ndarray);
	return dpstf2;
	/**
* Computes a complete-pivoting Cholesky factorization.
* @private
* @param {string|integer} order - layout
* @param {string|integer} uplo - triangle
* @param {integer} N - order
* @param {Float64Array} A - matrix
* @param {integer} LDA - leading dimension
* @param {Int32Array} PIV - positive one-based permutation output
* @param {Int32Array} RANK - rank output
* @param {number} TOL - tolerance
* @param {Float64Array} WORK - scratch
* @throws {TypeError} invalid selector
* @throws {RangeError} invalid metadata
* @returns {integer} INFO
*/
	function dpstf2(order, uplo, N, A, LDA, PIV, RANK, TOL, WORK) { // eslint-disable-line max-params
		var column;
		var r;
		var c;
		var u;
		if (((((order !== 'row-major') && (order !== 'column-major')) && (order !== 101)) && (order !== 102))) {
			throw new TypeError('invalid argument. Invalid layout.');
		}
		u = scalars(uplo, N, TOL);
		if (((!isSafeInteger(LDA) || (LDA < 1)) || (LDA < N))) {
			throw new RangeError('invalid argument. Invalid leading dimension.');
		}
		column = ((order === 'column-major') || (order === 102));
		r = ( column ) ? 1 : LDA;
		c = ( column ) ? LDA : 1;
		validate(N, A, r, c, 0, PIV, 1, 0, RANK, 0, WORK, 1, 0);
		return base(u, N, A, r, c, 0, PIV, 1, 0, RANK, 0, TOL, WORK, 1, 0);
	}
	/**
* Computes a factorization using independent indexed views.
* @private
* @param {string|integer} uplo - triangle
* @param {integer} N - order
* @param {Float64Array} A - matrix
* @param {integer} ra - row stride
* @param {integer} ca - column stride
* @param {integer} oa - matrix offset
* @param {Int32Array} P - permutation
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @param {Int32Array} R - rank
* @param {integer} orank - rank offset
* @param {number} tol - tolerance
* @param {Float64Array} W - scratch
* @param {integer} sw - scratch stride
* @param {integer} ow - scratch offset
* @returns {integer} INFO
*/
	function ndarray(uplo, N, A, ra, ca, oa, P, sp, op, R, orank, tol, W, sw, ow) { // eslint-disable-line max-params
		var u;
		u = scalars(uplo, N, tol);
		validate(N, A, ra, ca, oa, P, sp, op, R, orank, W, sw, ow);
		return base(u, N, A, ra, ca, oa, P, sp, op, R, orank, tol, W, sw, ow);
	}
}


// EXPORTS //

module.exports = factory;
